const items = $input.all();

const now = new Date();

// Current week: Monday through Sunday
const day = now.getDay();
const daysFromMonday = day === 0 ? 6 : day - 1;

const weekStart = new Date(now);
weekStart.setDate(now.getDate() - daysFromMonday);
weekStart.setHours(0, 0, 0, 0);

const weekEnd = new Date(weekStart);
weekEnd.setDate(weekStart.getDate() + 6);
weekEnd.setHours(23, 59, 59, 999);

let totalLeads = 0;
let qualifiedLeads = 0;
let newLeads = 0;

for (const item of items) {
  const properties = item.json.properties || {};

  const createDate =
    properties.createdate?.value ||
    properties.createdate ||
    null;

  const leadStatus = String(
    properties.hs_lead_status?.value ||
    properties.hs_lead_status ||
    ''
  ).toLowerCase();

  const lifecycleStage = String(
    properties.lifecyclestage?.value ||
    properties.lifecyclestage ||
    ''
  ).toLowerCase();

  // Count new leads created during the current week
  if (createDate) {
    const created = new Date(createDate);

    if (created >= weekStart && created <= weekEnd) {
      newLeads++;
    }
  }

  // Count contacts that are considered leads
  if (
    lifecycleStage === 'lead' ||
    lifecycleStage === 'marketingqualifiedlead' ||
    lifecycleStage === 'salesqualifiedlead' ||
    lifecycleStage === 'opportunity'
  ) {
    totalLeads++;
  }

  // Count qualified leads
  if (
    leadStatus.includes('qualified') ||
    lifecycleStage === 'salesqualifiedlead'
  ) {
    qualifiedLeads++;
  }
}

const qualificationRate =
  totalLeads > 0
    ? Number(((qualifiedLeads / totalLeads) * 100).toFixed(2))
    : 0;

return [
  {
    json: {
      reportWeekStart: weekStart.toISOString().split('T')[0],
      reportWeekEnd: weekEnd.toISOString().split('T')[0],
      totalLeads,
      newLeads,
      qualifiedLeads,
      qualificationRate
    }
  }
