const items = $input.all();

const now = new Date();

// Current reporting week: Monday to Sunday
const day = now.getDay();
const daysFromMonday = day === 0 ? 6 : day - 1;

const weekStart = new Date(now);
weekStart.setDate(now.getDate() - daysFromMonday);
weekStart.setHours(0, 0, 0, 0);

const weekEnd = new Date(weekStart);
weekEnd.setDate(weekStart.getDate() + 6);
weekEnd.setHours(23, 59, 59, 999);

let wonDeals = 0;
let lostDeals = 0;
let openDeals = 0;
let revenue = 0;

const wonDealValues = [];

for (const item of items) {

  const properties = item.json.properties || {};

  // Amount
  const amount = Number(
    properties.amount?.value ||
    properties.amount ||
    0
  );

  // Deal stage
  const dealStage = String(
    properties.dealstage?.value ||
    properties.dealstage ||
    ''
  ).toLowerCase().trim();

  // Close date
  const rawCloseDate =
    properties.closedate?.value ||
    properties.closedate ||
    null;

  let closeDate = null;

  if (rawCloseDate) {
    const numericDate = Number(rawCloseDate);

    // HubSpot returns Unix timestamp in milliseconds
    if (!isNaN(numericDate)) {
      closeDate = new Date(numericDate);
    } else {
      closeDate = new Date(rawCloseDate);
    }
  }

  // Check whether the deal closed during this reporting week
  const closedThisWeek =
    closeDate &&
    closeDate >= weekStart &&
    closeDate <= weekEnd;

  // WON
  if (dealStage === 'closedwon' && closedThisWeek) {
    wonDeals++;
    revenue += amount;
    wonDealValues.push(amount);
  }

  // LOST
  else if (dealStage === 'closedlost' && closedThisWeek) {
    lostDeals++;
  }

  // OPEN
  else if (
    dealStage !== 'closedwon' &&
    dealStage !== 'closedlost'
  ) {
    openDeals++;
  }
}

const averageDealValue =
  wonDealValues.length > 0
    ? Number(
        (
          wonDealValues.reduce((sum, value) => sum + value, 0) /
          wonDealValues.length
        ).toFixed(2)
      )
    : 0;

const totalClosedDeals = wonDeals + lostDeals;

const winRate =
  totalClosedDeals > 0
    ? Number(
        ((wonDeals / totalClosedDeals) * 100).toFixed(2)
      )
    : 0;

return [
  {
    json: {
      reportWeekStart: weekStart.toISOString().split('T')[0],
      reportWeekEnd: weekEnd.toISOString().split('T')[0],
      wonDeals,
      lostDeals,
      openDeals,
      revenue,
      averageDealValue,
      winRate
    }
  }
];

const tasks = $input.all();

const now = new Date();

// Start of current reporting week (Monday)
const weekStart = new Date(now);
const day = weekStart.getDay();
const diff = day === 0 ? -6 : 1 - day;
weekStart.setDate(weekStart.getDate() + diff);
weekStart.setHours(0, 0, 0, 0);

// End of current reporting week (Sunday)
const weekEnd = new Date(weekStart);
weekEnd.setDate(weekStart.getDate() + 6);
weekEnd.setHours(23, 59, 59, 999);

let totalTasks = 0;
let completedTasks = 0;
let pendingTasks = 0;
let overdueTasks = 0;

for (const item of tasks) {
  const data = item.json;

  // Only count actual tasks
  if (data.resource_type && data.resource_type !== 'task') {
    continue;
  }

  totalTasks++;

  const completed = data.completed === true;

  if (completed) {
    completedTasks++;
  } else {
    pendingTasks++;

    // Check whether the task is overdue
    const dueDate = data.due_on || data.due_at;

    if (dueDate) {
      const due = new Date(dueDate);

      if (due < now) {
        overdueTasks++;
      }
    }
  }
}

const completionRate = totalTasks > 0
  ? Number(((completedTasks / totalTasks) * 100).toFixed(2))
  : 0;

return [
  {
    json: {
      reportWeekStart: weekStart.toISOString().split('T')[0],
      reportWeekEnd: weekEnd.toISOString().split('T')[0],
      totalTasks,
      completedTasks,
      pendingTasks,
      overdueTasks,
      completionRate
    }
  }
];

